const ctx = $('Consolidar contexto').first().json;
let lista = $('Buffer: leer mensajes').first().json.mensajes_lista;
if (!Array.isArray(lista)) lista = lista ? [lista] : [];
// Redis push tail=true => orden cronológico. Unir con salto de línea.
const combinado = lista.filter(Boolean).join('\n').trim() || ctx.user_message;
return [{ json: Object.assign({}, ctx, { user_message: combinado }) }];

const ctx = $('Determinar rol').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.role && r.content).reverse();
const history = rows.map(r => ({ role: r.role, content: r.content }));
const historyText = history.map(h => h.role + ': ' + h.content).join('\n');
return [{ json: {
  empresa: ctx.empresa,
  nombre_empresa: ctx.nombre_empresa,
  nombre_asistente: ctx.nombre_asistente,
  rol: ctx.rol,
  rut_cliente: ctx.rut_cliente,
  from: ctx.from,
  phone_number_id: ctx.phone_number_id,
  user_message: ctx.user_message,
  message_id: ctx.message_id,
  history,
  history_text: historyText || '(sin historial previo)'
}}];

const ctx = $('Consolidar contexto').first().json;
const msg = (ctx.user_message || '').toLowerCase();
const wa = ctx.from;
// Detectar producto por palabras clave del catálogo real
let producto = null;
if (/empanad/.test(msg)) producto = 'Empanadas';
else if (/pastel|torta|kuchen|berlin|alfajor|brazo de reina|chilenito|delicia|dona/.test(msg)) producto = 'Pasteles';
else if (/\bpan\b|marraqueta|hallulla|molde|baguet/.test(msg)) producto = 'Pan';
else if (/sopaipilla/.test(msg)) producto = 'Sopaipillas';
// Señales de interés comercial
const interes = /(precio|valor|cu[aá]nto|cotiza|por mayor|mayorista|cantidad|docena|unidades|kilo|pedido|encargo|comprar|vender|local|negocio|restaurant|caf[eé]|almac[eé]n|sushi)/.test(msg);
// Registrar solo si hay producto identificado Y señal de interés
const debeRegistrar = !!producto && interes && !!wa;
return [{ json: { debeRegistrar, contact_id: wa, phone: wa, producto_interes: producto, estado_crm: 'En Conversación', origen_lead: 'whatsapp' } }];

const prev = $('Merge empresa+msg').first().json;
const rolRows = $input.all();
const rolRow = rolRows.length > 0 ? rolRows[0].json : {};
return [{ json: {
  ...prev,
  rol: rolRow.rol ?? 'anon',
  rut_cliente: rolRow.rut_cliente ?? null,
  nombre_contacto: rolRow.nombre ?? null
}}];

