const body = $input.first().json.body;
const value = body?.entry?.[0]?.changes?.[0]?.value ?? {};
const msg = value.messages?.[0] ?? {};
const metadata = value.metadata ?? {};

// Texto normal O respuesta de un botón/lista interactiva.
let userMessage = msg.text?.body ?? '';
if (msg.type === 'interactive') {
  const inter = msg.interactive ?? {};
  // El id que definimos en el menú (ej. 'ventas_mes') llega aquí; lo usamos como texto
  userMessage = inter.button_reply?.id || inter.list_reply?.id
             || inter.button_reply?.title || inter.list_reply?.title || '';
}

return [{ json: {
  from: msg.from ?? null,
  phone_number_id: metadata.phone_number_id ?? null,
  user_message: userMessage,
  message_id: msg.id ?? null,
  timestamp: msg.timestamp ?? null
}}];

const body = $input.first().json.body;
const value = body?.entry?.[0]?.changes?.[0]?.value ?? {};
const msg = value.messages?.[0] ?? {};
const metadata = value.metadata ?? {};
const type = msg.type;
const media = msg[type] ?? {};   // msg.audio / msg.image / msg.document
return [{ json: {
  from: msg.from ?? null,
  phone_number_id: metadata.phone_number_id ?? null,
  message_id: msg.id ?? null,
  timestamp: msg.timestamp ?? null,
  msg_type: type,
  media_id: media.id ?? null,
  mime_type: media.mime_type ?? null,
  filename: media.filename ?? null,
  caption: media.caption ?? '',      // pie de foto/documento si lo hay
  voice: media.voice ?? false
}}];

