={{ (() => {
  const b64 = $binary.data.data;
  const mime = $('Extraer media').first().json.mime_type || 'image/jpeg';
  const caption = $('Extraer media').first().json.caption || '';
  const instruccion = 'Eres el lector de imágenes de una panadería/pastelería mayorista chilena (empanadas, pasteles, pan, sopaipillas, insumos). Describe en español y de forma útil qué muestra esta imagen para atender al cliente. Si es un PRODUCTO de panadería, di qué producto parece (sabor/tipo de empanada, pastel, pan, etc.) para poder buscarlo en el catálogo. Si es un DOCUMENTO (lista de pedido, comprobante, factura, cotización), transcribe su texto y los ítems/cantidades. Sé conciso.' + (caption ? (' El cliente escribió junto a la imagen: \"' + caption + '\".') : '');
  return JSON.stringify({
    model: 'gpt-4o',
    messages: [{ role: 'user', content: [
      { type: 'text', text: instruccion },
      { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } }
    ]}],
    max_tokens: 500
  });
})() }}

