const empresaRow = $input.first().json;
// El shape de mensaje (from, user_message...) viene en el item que entró a
// "Resolver empresa": en texto = "Extraer campos"; en multimodal = "Normalizar *".
// "Resolver empresa" preserva el input previo vía $('...'), así que lo tomamos de
// la primera fuente disponible.
const srcNames = ['Extraer campos', 'Normalizar audio', 'Normalizar imagen', 'Normalizar documento'];
let extra = null;
for (const nm of srcNames) {
  try {
    const it = $(nm).first();
    if (it && it.json && it.json.from) { extra = it.json; break; }
  } catch (e) { /* nodo no ejecutado en esta rama */ }
}
extra = extra || {};
return [{ json: {
  empresa: empresaRow.empresa ?? null,
  nombre_empresa: empresaRow.nombre_empresa ?? 'la empresa',
  nombre_asistente: empresaRow.nombre_asistente ?? 'Asistente',
  from: extra.from,
  phone_number_id: extra.phone_number_id,
  user_message: extra.user_message,
  message_id: extra.message_id
}}];

const meta = $('Extraer media').first().json;
const texto = ($input.first().json.text || '').trim();
return [{ json: {
  from: meta.from,
  phone_number_id: meta.phone_number_id,
  user_message: texto || '(nota de voz vacía)',
  message_id: meta.message_id,
  timestamp: meta.timestamp
}}];

const meta = $('Extraer media').first().json;
const texto = ($input.first().json.text || '').trim();
const caption = (meta.caption || '').trim();
const nombre = meta.filename || 'documento';
let user_message;
if (texto) {
  user_message = '[El cliente envió un DOCUMENTO (' + nombre + '). Contenido extraído: ' + texto.slice(0, 4000) + ']';
} else {
  user_message = '[El cliente envió un DOCUMENTO (' + nombre + ') pero no pude extraer texto (puede ser un PDF escaneado o una imagen). Pídele amablemente que te lo mande como foto o que escriba lo que necesita.]';
}
if (caption) user_message += '\nTexto del cliente: ' + caption;
return [{ json: {
  from: meta.from,
  phone_number_id: meta.phone_number_id,
  user_message,
  message_id: meta.message_id,
  timestamp: meta.timestamp
}}];

const meta = $('Extraer media').first().json;
const resp = $input.first().json;
const lectura = resp?.choices?.[0]?.message?.content?.trim() || '(no pude leer la imagen)';
const caption = (meta.caption || '').trim();
const user_message = '[El cliente envió una IMAGEN. Lectura automática: ' + lectura + ']' + (caption ? ('\nTexto del cliente: ' + caption) : '');
return [{ json: {
  from: meta.from,
  phone_number_id: meta.phone_number_id,
  user_message,
  message_id: meta.message_id,
  timestamp: meta.timestamp
}}];

