const body = $('Switch tipo mensaje').first().json.body;
const value = body?.entry?.[0]?.changes?.[0]?.value ?? {};
const msg = value.messages?.[0] ?? {};
const metadata = value.metadata ?? {};
// Si NO es un mensaje real del usuario (ej. statuses), no responder nada.
